  return {
    "flow": "MARKET_STORE",
    "app_url": "SET_IN_STUDIO_APP_URL",
    "inbound_token": "SET_IN_STUDIO_INBOUND_TOKEN",
    "auto_send": true,
    "broadcast_webhook": "SET_IN_STUDIO_BROADCAST_WEBHOOK_URL"
